41	func newMetricsExporter(params exporter.Settings, cfg component.Config) (*metricExporterImp, error) {
42		telemetry, err := metadata.NewTelemetryBuilder(params.TelemetrySettings)
43		if err != nil {
44			return nil, err
45		}
46		exporterFactory := otlpexporter.NewFactory()
47		cfFunc := func(ctx context.Context, endpoint string) (component.Component, error) {
48			oCfg := buildExporterConfig(cfg.(*Config), endpoint)
49			oParams := buildExporterSettings(exporterFactory.Type(), params, endpoint)
50	
51			return exporterFactory.CreateMetrics(ctx, oParams, &oCfg)
52		}
53	
54		lb, err := newLoadBalancer(params.Logger, cfg, cfFunc, telemetry)
55		if err != nil {
56			return nil, err
57		}
58	
59		metricExporter := metricExporterImp{
60			loadBalancer: lb,
61			routingKey:   svcRouting,
62			telemetry:    telemetry,
63			logger:       params.Logger,
64		}
65	
66		switch cfg.(*Config).RoutingKey {
67		case svcRoutingStr, "":
68			// default case for empty routing key
69			metricExporter.routingKey = svcRouting
70		case resourceRoutingStr:
71			metricExporter.routingKey = resourceRouting
72		case metricNameRoutingStr:
73			metricExporter.routingKey = metricNameRouting
74		case streamIDRoutingStr:
75			metricExporter.routingKey = streamIDRouting
76		default:
77			return nil, fmt.Errorf("unsupported routing_key: %q", cfg.(*Config).RoutingKey)
78		}
79		return &metricExporter, nil
80	}
